package esprit.canditature.dto;

/**
 * Copy of the JSON returned by the candidat microservice (not a JPA entity:
 * candidature does not own candidates, it only reads them through Feign).
 *
 * JSON received:
 * {"id":1,"firstname":"Badia","lastname":"Abouhdid","email":"badia@example.com",
 *  "address":{"id":1,"street":"...","houseNumber":"12B","zipCode":"1001","candidateId":1}}
 *
 * A record = constructor + accessors generated by Java: the component names
 * (firstname, lastname...) are exactly the JSON keys, so Jackson fills every field.
 */
public record Candidate(
        Long id,
        String firstname,
        String lastname,
        String email,
        Address address
) {
}
